CREATE POLICY "scope thread changes" ON public.forum_threads AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.portal_access(auth.uid()) AND (branch_id IS NULL OR branch_id=public.portal_branch() OR public.has_role(auth.uid(),'admin_national'))) WITH CHECK (public.portal_access(auth.uid()) AND (branch_id IS NULL OR branch_id=public.portal_branch() OR public.has_role(auth.uid(),'admin_national')));
CREATE POLICY "scope thread deletes" ON public.forum_threads AS RESTRICTIVE FOR DELETE TO authenticated USING (public.portal_access(auth.uid()) AND (branch_id IS NULL OR branch_id=public.portal_branch() OR public.has_role(auth.uid(),'admin_national')));
CREATE POLICY "scope post changes" ON public.forum_posts AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.portal_access(auth.uid()) AND EXISTS(SELECT 1 FROM public.forum_threads t WHERE t.id=thread_id)) WITH CHECK (public.portal_access(auth.uid()) AND EXISTS(SELECT 1 FROM public.forum_threads t WHERE t.id=thread_id));
CREATE POLICY "scope post deletes" ON public.forum_posts AS RESTRICTIVE FOR DELETE TO authenticated USING (public.portal_access(auth.uid()) AND EXISTS(SELECT 1 FROM public.forum_threads t WHERE t.id=thread_id));